",".nav-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 background: #060911;
 border-bottom: 1px solid #1a2035;
 padding: 0 24px;
 height: 56px;
 position: sticky;
 top: 0;
 z-index: 100;
}

/* ─── Left: Logo + Wordmark + Pill ─── */
.nav-header__left {
 display: flex;
 align-items: center;
 gap: 10px;
}

.nav-header__logo-mark {
 display: flex;
 align-items: center;
 justify-content: center;
}

.nav-header__wordmark {
 font-size: 16px;
 font-weight: 700;
 color: #e2e8f0;
 letter-spacing: -0.3px;
}

.nav-header__pill {
 font-size: 10px;
 font-weight: 600;
 color: #64748b;
 letter-spacing: 0.8px;
 background: rgba(255, 255, 255, 0.05);
 border: 1px solid #1a2035;
 border-radius: 20px;
 padding: 3px 10px;
 text-transform: uppercase;
}

/* ─── Center: Nav Tabs ─── */
.nav-header__center {
 display: flex;
 align-items: center;
 gap: 2px;
}

.nav-header__tab {
 padding: 7px 16px;
 border-radius: 6px;
 font-size: 13px;
 font-weight: 500;
 color: #64748b;
 text-decoration: none;
 transition: color 0.15s ease, background 0.15s ease;
}

.nav-header__tab:hover {
 color: #cbd5e1;
}

.nav-header__tab--active {
 color: #ffffff;
 font-weight: 600;
 background: rgba(255, 255, 255, 0.07);
}

/* ─── Right: Search, Bell, Date, Avatar ─── */
.nav-header__right {
 display: flex;
 align-items: center;
 gap: 12px;
}

.nav-header__search {
 display: flex;
 align-items: center;
 gap: 8px;
 background: rgba(255, 255, 255, 0.04);
 border: 1px solid #1a2035;
 border-radius: 8px;
 padding: 6px 12px;
}

.nav-header__search-icon {
 color: #64748b;
 flex-shrink: 0;
}

.nav-header__search-input {
 background: none;
 border: none;
 outline: none;
 color: #e2e8f0;
 font-size: 12px;
 width: 170px;
}

.nav-header__search-input::placeholder {
 color: #64748b;
}

.nav-header__bell {
 display: flex;
 align-items: center;
 justify-content: center;
 background: none;
 border: none;
 color: #64748b;
 cursor: pointer;
 padding: 6px;
 border-radius: 6px;
 position: relative;
 transition: color 0.15s ease;
}

.nav-header__bell:hover {
 color: #e2e8f0;
}

.nav-header__badge {
 position: absolute;
 top: 0;
 right: 0;
 background: #ef4444;
 color: #fff;
 font-size: 9px;
 font-weight: 700;
 width: 16px;
 height: 16px;
 border-radius: 50%;
 display: flex;
 align-items: center;
 justify-content: center;
 line-height: 1;
}

.nav-header__date-pill {
 display: flex;
 align-items: center;
 gap: 6px;
 background: rgba(255, 255, 255, 0.04);
 border: 1px solid #1a2035;
 border-radius: 20px;
 padding: 5px 12px;
 color: #94a3b8;
 font-size: 12px;
 cursor: pointer;
 transition: border-color 0.15s ease;
}

.nav-header__date-pill:hover {
 border-color: #334155;
}

.nav-header__avatar {
 width: 32px;
 height: 32px;
 border-radius: 50%;
 background: #3b82f6;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 11px;
 font-weight: 700;
 color: #fff;
 letter-spacing: 0.5px;
}
